struct Mutation: Codable, Sendable {
    let id: UUID                 // idempotency key
    let entity: String
    let entityID: UUID
    let op: Op                   // .upsert(fields) / .delete
    let baseVersion: Int?
    let createdAt: Date
}

actor SyncEngine {
    func sync() async throws {
        for m in try store.pendingMutations() {          // ordered
            switch try await api.push(m) {
            case .applied(let version): try store.markSynced(m, version: version)
            case .conflict(let server): try store.resolve(m, server: server, policy: policy(for: m.entity))
            case .rejected(let reason): try store.rollback(m, reason: reason)
            }
        }
        let page = try await api.changes(since: store.cursor)
        try store.apply(page.changes, newCursor: page.cursor)   // one transaction
    }
}
